import { IconButton } from '@Pimcore/components/icon-button/icon-button'
import React from 'react'
import { useSearch } from '../../provider/use-search'

export const SearchButton = (): React.JSX.Element => {
  const { open } = useSearch()

  return (
    <IconButton
      icon={ { value: 'search' } }
      onClick={ () => { open() } }
      type='text'
    />
  )
}
